test('renderInvoiceText shows total paid with multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  let invoice = issuedResult.value;

  const payment1 = recordPayment(invoice, 5000);
